/**
 * Resolves a search hit to the page the app actually serves. A comment has no
 * page of its own, so a comment hit links to the issue it was posted on —
 * same destination a reader would want from a comment notification.
 */
async function hrefFor(
  org: Organization,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string | null> {
  switch (kind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(org.id, subjectId as IssueId);
      if (!issue) return null;
      return hrefForIssue(org, issue);
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        org.id,
        subjectId as CommentId,
      );
      if (!comment) return null;
      const issue = await issueRepo.findIssueById(org.id, comment.issueId);
      if (!issue) return null;
      return hrefForIssue(org, issue);
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        org.id,
        subjectId as ProjectId,
      );
      if (!project) return null;
      return projectPath(org.slug, project.slug);
    }
  }
}

async function hrefForIssue(org: Organization, issue: Issue): Promise<string | null> {
  const project = await projectRepo.findProjectById(org.id, issue.projectId);
  if (!project) return null;
  return issuePath(org.slug, project.slug, issue.number);
}

