1	/**
2	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
5	 */
6	import { subscribe } from "@/lib/event-bus";
7	import { isEnabled } from "@/lib/feature-flags";
8	import { assertCan } from "@/lib/permissions";
9	import { assertOrgScope } from "@/lib/tenant";
10	import { issuePath, settingsPath, withSearchParams } from "@/lib/url";
11	import * as issueRepo from "@/server/repositories/issue-repository";
12	import * as notificationRepo from "@/server/repositories/notification-repository";
13	import * as orgRepo from "@/server/repositories/organization-repository";
14	import * as projectRepo from "@/server/repositories/project-repository";
15	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
16	import { toIsoTimestamp } from "@/types/common";
17	import { notificationResource, requireFound } from "./_support";
18	import type {
19	  ListNotificationsInput,
20	  MarkNotificationReadInput,
21	  UpdateNotificationPreferenceInput,
22	} from "@/schemas/notification";
23	import type { OrgId, Page, UserId } from "@/types/common";
24	import type { FlagContext } from "@/types/feature-flag";
25	import type { Issue } from "@/types/issue";
26	import type { Actor } from "@/types/member";
27	import type {
28	  Notification,
29	  NotificationChannel,
30	  NotificationKind,
31	  NotificationPreference,
32	} from "@/types/notification";
33	
34	export type NotificationPayload = {
35	  title: string;
36	  body: string;
37	  href: string;
38	  actorId: UserId | null;
39	};
40	
41	/** Channels used when a recipient has never touched their preferences. */
42	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
43	
44	/**
45	 * Writes one notification row per recipient, each with the channel set that
46	 * recipient's preferences allow. A recipient who has muted every channel is
47	 * skipped entirely rather than given a row nobody will ever see.
48	 */
49	export async function notify(
50	  orgId: OrgId,
51	  kind: NotificationKind,
52	  recipients: readonly UserId[],
53	  payload: NotificationPayload,
54	): Promise<readonly Notification[]> {
55	  if (recipients.length === 0) return [];
56	
57	  const org = await orgRepo.findOrgById(orgId);
58	  const flags: FlagContext = {
59	    orgId,
60	    userId: payload.actorId,
61	    plan: org?.plan ?? "free",
62	    role: null,
63	    overrides: org?.settings.enabledFlagOverrides,
64	  };
65	
66	  const rows = [];
67	
68	  for (const recipientId of new Set(recipients)) {
69	    if (recipientId === payload.actorId) continue;
70	
71	    const preference = await preferenceRepo.getPreference(
72	      orgId,
73	      recipientId,
74	      kind,
75	    );
76	    const channels = resolveChannels(preference, flags);
77	    if (channels.length === 0) continue;
78	
79	    rows.push({
80	      orgId,
81	      recipientId,
82	      kind,
83	      title: payload.title,
84	      body: payload.body,
85	      href: payload.href,
86	      actorId: payload.actorId,
87	      channels,
88	    });
89	  }
90	
91	  return notificationRepo.insertNotifications(orgId, rows);
92	}
93	
94	export async function listNotifications(
95	  actor: Actor,
96	  input: ListNotificationsInput,
97	): Promise<Page<Notification>> {
98	  assertOrgScope(actor, input.orgId);
99	  assertCan(
100	    actor,
101	    "notification:read",
102	    notificationResource(input.orgId, input.recipientId),
103	  );
104	  return notificationRepo.listNotifications(input);
105	}
106	
107	export async function markRead(
108	  actor: Actor,
109	  input: MarkNotificationReadInput,
110	): Promise<Notification> {
111	  assertOrgScope(actor, input.orgId);
112	  assertCan(
113	    actor,
114	    "notification:manage",
115	    notificationResource(input.orgId, actor.userId),
116	  );
117	  return notificationRepo.markRead(
118	    input.orgId,
119	    actor.userId,
120	    input.notificationId,
121	    toIsoTimestamp(new Date()),
122	  );
123	}
124	
125	export async function markAllRead(
126	  actor: Actor,
127	  orgId: OrgId,
128	): Promise<number> {
129	  assertOrgScope(actor, orgId);
130	  assertCan(
131	    actor,
132	    "notification:manage",
133	    notificationResource(orgId, actor.userId),
134	  );
135	  return notificationRepo.markAllRead(
136	    orgId,
137	    actor.userId,
138	    toIsoTimestamp(new Date()),
139	  );
140	}
141	
142	export async function updatePreference(
143	  actor: Actor,
144	  input: UpdateNotificationPreferenceInput,
145	): Promise<NotificationPreference> {
146	  assertOrgScope(actor, input.orgId);
147	  assertCan(
148	    actor,
149	    "notification:manage",
150	    notificationResource(input.orgId, input.userId),
151	  );
152	  return preferenceRepo.upsertPreference(input);
153	}
154	
155	/**
156	 * Turns a stored preference into the channels one notification will use.
157	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
158	 * the email channel additionally requires the org's `digest_email` plan flag.
159	 */
160	export function resolveChannels(
161	  preference: NotificationPreference | null,
162	  flags: FlagContext,
163	): readonly NotificationChannel[] {
164	  if (preference === null) return DEFAULT_CHANNELS;
165	
166	  const channels: NotificationChannel[] = [];
167	  if (preference.inApp) channels.push("in_app");
168	
169	  const emailAllowed =
170	    preference.email &&
171	    (!preference.digestOnly || isEnabled("digest_email", flags));
172	
173	  if (emailAllowed) channels.push("email");
174	  return channels;
175	}
176	
177	/**
178	 * Resolves the in-app page an issue actually lives at. `null` when the issue,
179	 * its project or the organization cannot be found — callers treat that as
180	 * "nothing to link to yet" and skip the notification rather than writing a
181	 * row that points nowhere.
182	 */
183	async function hrefForIssue(orgId: OrgId, issue: Issue): Promise<string | null> {
184	  const [org, project] = await Promise.all([
185	    orgRepo.findOrgById(orgId),
186	    projectRepo.findProjectById(orgId, issue.projectId),
187	  ]);
188	  if (!org || !project) return null;
189	  return issuePath(org.slug, project.slug, issue.number);
190	}
191	
192	/**
193	 * The bus wiring. Attached at module load rather than from `event-registry`
194	 * because the fan-out has no other public entry point — importing this module
195	 * is what makes an org start receiving notifications.
196	 */
197	let registered = false;
198	
199	function registerFanOut(): void {
200	  if (registered) return;
201	  registered = true;
202	
203	  // Being assigned at creation is an assignment: the creator is excluded by
204	  // `notify()`'s actor check exactly as a later `issue.assigned` would be.
205	  subscribe("issue.created", async (payload) => {
206	    if (payload.assigneeId === null) return;
207	
208	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
209	    if (!issue) return;
210	    const href = await hrefForIssue(payload.orgId, issue);
211	    if (!href) return;
212	
213	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
214	      title: "You were assigned an issue",
215	      body: `Issue "${issue.title}" is now yours`,
216	      href,
217	      actorId: payload.actorId,
218	    });
219	  });
220	
221	  subscribe("issue.assigned", async (payload) => {
222	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
223	    if (!issue) return;
224	    const href = await hrefForIssue(payload.orgId, issue);
225	    if (!href) return;
226	
227	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
228	      title: "You were assigned an issue",
229	      body: `Issue "${issue.title}" is now yours`,
230	      href,
231	      actorId: payload.actorId,
232	    });
233	  });
234	
235	  // Status changes are only interesting to the assignee, including a move on
236	  // the board (`moveIssue` is a thin wrapper over `changeIssueStatus`), and
237	  // only when somebody else made the change.
238	  subscribe("issue.status_changed", async (payload) => {
239	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
240	    if (!issue || issue.assigneeId === null) return;
241	    const href = await hrefForIssue(payload.orgId, issue);
242	    if (!href) return;
243	
244	    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
245	      title: "Issue status changed",
246	      body: `Issue "${issue.title}" moved from ${payload.from} to ${payload.to}`,
247	      href,
248	      actorId: payload.actorId,
249	    });
250	  });
251	
252	  subscribe("issue.overdue", async (payload) => {
253	    if (payload.assigneeId === null) return;
254	
255	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
256	    if (!issue) return;
257	    const href = await hrefForIssue(payload.orgId, issue);
258	    if (!href) return;
259	
260	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
261	      title: "An issue is overdue",
262	      body: `Issue "${issue.title}" was due ${payload.dueAt}`,
263	      href,
264	      actorId: null,
265	    });
266	  });
267	
268	  subscribe("comment.created", async (payload) => {
269	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
270	    if (!issue) return;
271	    const href = await hrefForIssue(payload.orgId, issue);
272	    if (!href) return;
273	
274	    const watchers = [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])];
275	
276	    await notify(payload.orgId, "comment_created", watchers, {
277	      title: "New comment",
278	      body: `A comment was added to issue "${issue.title}"`,
279	      href,
280	      actorId: payload.actorId,
281	    });
282	
283	    if (payload.mentionedUserIds.length > 0) {
284	      await notify(
285	        payload.orgId,
286	        "comment_mention",
287	        payload.mentionedUserIds,
288	        {
289	          title: "You were mentioned",
290	          body: `You were mentioned on issue "${issue.title}"`,
291	          href,
292	          actorId: payload.actorId,
293	        },
294	      );
295	    }
296	  });
297	
298	  // The owner is the one who needs to know headcount moved; the person who
299	  // joined already knows they joined.
300	  subscribe("member.joined", async (payload) => {
301	    const org = requireFound(
302	      await orgRepo.findOrgById(payload.orgId),
303	      "Organization",
304	      payload.orgId,
305	    );
306	    await notify(payload.orgId, "member_joined", [org.ownerId], {
307	      title: "A new member joined",
308	      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
309	      href: settingsPath(org.slug, "members"),
310	      actorId: payload.actorId,
311	    });
312	  });
313	
314	  // Only a refusal reaches this event (the periodic usage recount never
315	  // emits it), and the owner is told once per resource per unread alert —
316	  // further refusals for the same resource are folded in until it is read.
317	  subscribe("billing.limit_exceeded", async (payload) => {
318	    const org = await orgRepo.findOrgById(payload.orgId);
319	    if (!org) return;
320	
321	    const href = withSearchParams(settingsPath(org.slug, "billing"), {
322	      resource: payload.resource,
323	    });
324	
325	    const existing = await notificationRepo.findUnreadByHref(
326	      payload.orgId,
327	      org.ownerId,
328	      "plan_limit_reached",
329	      href,
330	    );
331	    if (existing) return;
332	
333	    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
334	      title: "Plan limit reached",
335	      body: `Your plan allows ${payload.limit} ${payload.resource}; ${payload.used} are in use`,
336	      href,
337	      actorId: null,
338	    });
339	  });
340	}
341	
342	registerFanOut();
343

